arguments.command:
bash -lc 'pwd; echo "\n-- ls .git/modules/memory-api/worktrees --"; ls -la .git/modules/memory-api/worktrees/ 2>/dev/null || echo "(no entries)"; echo "\n-- cat each gitdir (if any) --"; for g in .git/modules/memory-api/worktrees/*/gitdir; do echo "$g:"; cat "$g"; test -e "$(cat $g)" && echo "TARGET_EXISTS" || echo "TARGET_MISSING"; done || true

echo "\n-- grep for exact worktrees path --";
grep -R --line-number "worktrees/5cd0b38e-session" .git/ 2>/dev/null || true

echo "\n-- grep for 5cd0b38e-session --";
grep -R --line-number "5cd0b38e-session" .git/ 2>/dev/null || true

echo "\n-- grep for 5cd0b38e anywhere under .git but filter .worktrees hits --";
grep -R --line-number "5cd0b38e" .git/ 2>/dev/null | grep "/.worktrees/" || true

echo "\n-- list superproject worktrees --";
ls -la .git/worktrees/ 2>/dev/null || echo "(no entries)"
for g in .git/worktrees/*/gitdir; do echo "$g:"; cat "$g"; test -e "$(cat $g)" && echo "TARGET_EXISTS" || echo "TARGET_MISSING"; done || true

echo "\n-- memory-api/.git content --";
if [ -f memory-api/.git ]; then echo "memory-api/.git:"; cat memory-api/.git; fi

echo "\n-- git config mentions of .worktrees --";
git config --get-regexp "worktrees" 2>/dev/null || true

echo "\n-- git config submodule entries referencing .worktrees --";
git config --get-regexp "^submodule\." 2>/dev/null | grep ".worktrees" || true
'

bash -lc 'echo "pwd: $(pwd)"; echo "\n-- cat .git/modules/memory-api/config --"; sed -n "1,200p" .git/modules/memory-api/config || true

echo "\n-- other submodules: memory-viewers context-stack viewer-api memory-kernel worktrees --";
for m in memory-viewers context-stack viewer-api memory-kernel; do
  echo "\n== $m ==";
  ls -la .git/modules/$m/worktrees/ 2>/dev/null || echo "(no entries)";
  for g in .git/modules/$m/worktrees/*/gitdir; do
    if [ -f "$g" ]; then
      echo "$g:"; cat "$g"; test -e "$(cat $g)" && echo "TARGET_EXISTS" || echo "TARGET_MISSING";
    fi
  done
done

echo "\n-- git -C memory-api worktree list --";
git -C memory-api worktree list 2>&1 || true
'
